{
  "wildcard_fields": [
    "container_name",
    "custom_name",
    "licensed_apps",
    "region",
    "notes"
  ],
  "filters": [
    {
      "name": "container_name",
      "readable_name": "Account Name",
      "control": {
        "readable_regex": "TEXT",
        "type": "entry",
        "regex": ".*"
      },
      "operators": [
        "eq",
        "neq",
        "match",
        "nmatch"
      ]
    },
    {
      "name": "uuid",
      "readable_name": "Account UUID",
      "control": {
        "readable_regex": "01234567-abcd-ef01-2345-6789abcdef01",
        "type": "entry",
        "regex": "[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12}(,[0-9a-f]{8}-([0-9a-f]{4}-){3}[0-9a-f]{12})*"
      },
      "operators": [
        "eq",
        "neq"
      ]
    },
    {
      "name": "licensed_assets",
      "readable_name": "Licenses Provisioned",
      "control": {
        "readable_regex": "e.g. 1111111,2222222",
        "type": "entry",
        "regex": "0|(-?[1-9][0-9]*)"
      },
      "operators": [
        "lte",
        "gte",
        "lt",
        "gt",
        "eq",
        "neq"
      ]
    },
    {
      "name": "license_utilization",
      "readable_name": "License Utilization",
      "control": {
        "readable_regex": "e.g. 1111111,2222222",
        "type": "entry",
        "regex": "0|(-?[1-9][0-9]*)"
      },
      "operators": [
        "lte",
        "gte",
        "lt",
        "gt",
        "eq",
        "neq"
      ]
    },
    {
      "name": "license_expiration_date",
      "readable_name": "License Expiring",
      "control": {
        "readable_regex": "Enter no. of days, eg. 90",
        "type": "entry",
        "regex": "^[0-9]+$",
        "maxlength": "6"
      },
      "operators": [
        "lte",
        "gte",
        "lt",
        "gt"
      ]
    },
    {
      "name": "licensed_apps",
      "readable_name": "Licensed Apps",
      "control": {
        "type": "dropdown_multi",
        "list": [
          {
            "name": "WAS",
            "id": "was"
          },
          {
            "name": "LUMIN",
            "id": "lumin"
          }
        ]
      },
      "operators": [
        "eq",
        "neq"
      ]
    },
    {
      "name": "region",
      "readable_name": "Region",
      "control": {
        "type": "dropdown_multi",
        "list": [
          {
            "name": "QA-STAGING",
            "id": "qa-staging"
          }
        ]
      },
      "operators": [
        "eq",
        "neq"
      ]
    }
  ]
}

