{
  "wildcard_fields": [
    "core_version",
    "distro",
    "groups",
    "ip",
    "name",
    "platform",
    "status"
  ],
  "filters": [
    {
      "name": "core_version",
      "readable_name": "Version",
      "operators": [
        "match",
        "lt",
        "neq",
        "eq",
        "nmatch",
        "gt"
      ],
      "control": {
        "readable_regex": "X.Y.Z",
        "type": "entry",
        "regex": ".*"
      }
    },
    {
      "name": "distro",
      "readable_name": "Distro",
      "operators": [
        "match",
        "nmatch"
      ],
      "control": {
        "readable_regex": "Distro Name (e.g. es7-x86-64)",
        "type": "entry",
        "regex": ".*"
      }
    },
    {
      "name": "groups",
      "readable_name": "Member of Group",
      "operators": [
        "eq",
        "neq"
      ],
      "control": {
        "type": "dropdown",
        "list": [
          {
            "name": "None",
            "id": -1
          },
          {
            "name": "NA1",
            "id": 738777
          }
        ]
      }
    },
    {
      "name": "ip",
      "readable_name": "IP Address",
      "operators": [
        "eq",
        "neq",
        "match",
        "nmatch"
      ],
      "control": {
        "readable_regex": "192.168.1.1",
        "type": "entry",
        "regex": ".*"
      }
    },
    {
      "name": "last_connect",
      "readable_name": "Last Connection",
      "operators": [
        "date-lt",
        "date-gt",
        "date-eq",
        "date-neq",
        "lt",
        "gt",
        "exists",
        "nexists"
      ],
      "control": {
        "readable_regex": "yyyy/MM/dd OR 1234567890",
        "type": "datefield",
        "regex": "^(?:[0-9]{4}/[0-9]{2}/[0-9]{2}|[0-9]{1,11})$"
      }
    },
    {
      "name": "last_scanned",
