        "readable_regex": "yyyy/MM/dd OR 1234567890",
        "type": "datefield",
        "regex": "^(?:[0-9]{4}/[0-9]{2}/[0-9]{2}|[0-9]{1,11})$"
      }
    },
    {
      "name": "name",
      "readable_name": "Name",
      "operators": [
        "eq",
        "neq",
        "match",
        "nmatch"
      ],
      "control": {
        "readable_regex": "TEXT",
        "type": "entry",
        "regex": ".*"
      }
    },
    {
      "name": "platform",
      "readable_name": "Platform",
      "operators": [
        "eq",
        "neq",
        "match",
        "nmatch"
      ],
      "control": {
        "readable_regex": "Platform Name (e.g. Linux)",
        "type": "entry",
        "regex": ".*"
      }
    },
    {
      "name": "plugin_feed_id",
      "readable_name": "Last Plugin Update",
      "operators": [
        "date-lt",
        "date-gt",
        "date-eq",
        "date-neq",
        "lt",
        "gt",
        "exists",
        "nexists"
      ],
      "control": {
        "readable_regex": "yyyy/MM/dd OR 1234567890",
        "type": "datefield",
        "regex": "^(?:[0-9]{4}/[0-9]{2}/[0-9]{2}|[0-9]{1,11})$"
      }
    },
    {
      "name": "status",
      "readable_name": "Status",
      "operators": [
        "eq",
        "neq"
      ],
      "control": {
        "type": "dropdown",
        "list": [
          "Online",
          "Offline",
          "Initializing"
        ]
      }
    },
    {
      "name": "uuid",
      "readable_name": "UUID",
      "operators": [
        "eq",
        "neq"
      ],
      "control": {
        "readable_regex": "agent uuid",
        "type": "entry",
        "regex": ".*"
      }
    },
    {
      "name": "network_uuid",
      "readable_name": "Network UUID",
      "operators": [
        "eq",
        "neq"
      ],
      "control": {
        "readable_regex": "Network UUID",
        "type": "entry",
        "regex": ".*"
      }
    },
    {
      "name": "network_name",
      "readable_name": "Network Name",
      "operators": [
        "eq",
        "neq"
      ],
      "control": {
        "readable_regex": "Network Name",
        "type": "entry",
        "regex": ".*"
      }
    },
    {
