        "eq",
        "neq"
      ],
      "control": {
        "type": "dropdown",
        "list": [
          {
            "name": "Default",
            "id": "00000000-0000-0000-0000-000000000000"
          },
          {
            "name": "NA1",
            "id": "e302aaa5-aaa5-aaa5-aaa5-703dd25faaa5"
          }
        ]
      }
    },
    {
      "name": "health",
      "readable_name": "Health",
      "operators": [
        "eq",
        "neq"
      ],
      "control": {
        "type": "dropdown",
        "list": [
          "Healthy",
          "Warning",
          "Critical",
          "Safe Mode",
          "Unknown"
        ]
      }
    },
    {
      "name": "safe_mode",
      "readable_name": "Safe Mode",
      "operators": [
        "eq",
        "neq"
      ],
      "control": {
        "type": "dropdown",
        "list": [
          "Enabled",
          "Disabled",
          "N/A"
        ]
      }
    },
    {
      "name": "linked_on",
      "readable_name": "Linked On",
      "operators": [
